import{_ as l,a0 as d,w as a,s as u,ao as p,I as i,x as e,a1 as o,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在笔记本电脑合盖时不挂起 Ubuntu | LCTT x X-CMD","titleTemplate":false,"description":"如何在笔记本电脑合盖时不挂起 Ubuntu | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在笔记本电脑合盖时不挂起 Ubuntu | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在笔记本电脑合盖时不挂起 Ubuntu | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220831 Don-t Suspend Ubuntu When Laptop Lid is Closed","title":"如何在笔记本电脑合盖时不挂起 Ubuntu","tag":"202209","desc":""},"relativePath":"202209/20220831 Don-t Suspend Ubuntu When Laptop Lid is Closed.md","filePath":"[post].md"}'),r={name:"202209/20220831 Don-t Suspend Ubuntu When Laptop Lid is Closed.md"};function b(m,t,f,g,h,T){const s=d("Link");return a(),u("div",null,[t[18]||(t[18]=p('<h1 id="如何在笔记本电脑合盖时不挂起-ubuntu" tabindex="-1">如何在笔记本电脑合盖时不挂起 Ubuntu <a class="header-anchor" href="#如何在笔记本电脑合盖时不挂起-ubuntu" aria-label="Permalink to “如何在笔记本电脑合盖时不挂起 Ubuntu”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202209/09/230733ppyyws84ccgrc777.jpg" alt=""></p><p>如果你在笔记本电脑上使用 Ubuntu，你可能已经注意到当你合上盖子时系统处于挂起状态。</p><p>这是预期的行为。它可以节省电池和你的工作。你掀开盖子，系统唤醒，你可以登录并继续工作。</p><p>这一切听起来都不错，除非你使用多显示器设置。像我这样的一些人更喜欢关闭笔记本电脑，只使用外接显示器。</p><p>但是，如果关闭笔记本电脑盖会挂起系统，那么会产生问题。</p><p>让我告诉你如何改变这种行为。</p><h3 id="关闭笔记本电脑盖时不要挂起" tabindex="-1">关闭笔记本电脑盖时不要挂起 <a class="header-anchor" href="#关闭笔记本电脑盖时不要挂起" aria-label="Permalink to “关闭笔记本电脑盖时不要挂起”">​</a></h3><p>实际上，我注意到最近的 Ubuntu 版本在这个情况下更智能。当笔记本电脑连接到扩展坞并合上盖子时，它不会进入挂起模式。</p><p>这是正常的预期行为，但由于 Ubuntu 某种神才知道的原因，它可能不会一直有效。</p><p>好消息是你可以使用 GUI 和命令行强制更改此行为。</p><p>让我分享这两种方法。</p><h4 id="方法-1-使用-gnome-优化" tabindex="-1">方法 1：使用 GNOME 优化 <a class="header-anchor" href="#方法-1-使用-gnome-优化" aria-label="Permalink to “方法 1：使用 GNOME 优化”">​</a></h4>',13)),i("p",null,[t[1]||(t[1]=e("如果你使用的是默认的 GNOME 桌面，那么你很幸运。 ",-1)),o(s,{href:"https://itsfoss.com/gnome-tweak-tool/"},{default:n(()=>[...t[0]||(t[0]=[e("在 Ubuntu 的软件中心安装 GNOME 优化（Tweaks）工具",-1)])]),_:1}),t[2]||(t[2]=e("，或使用以下命令：",-1))]),t[19]||(t[19]=p('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install gnome-tweaks</span></span></code></pre></div><p>安装后，启动优化应用。在侧边栏的<ruby>常规<rt>General</rt></ruby>选项卡中，关闭“<ruby>笔记本电脑盖合上时挂起<rt>Suspend when laptop lid is closed</rt></ruby>”按钮。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/change-lid-close-behavior-ubuntu.png" alt="change lid close behavior ubuntu"></p><p>这就好了。你不需要重启即可使更改生效。</p><p>现在，让我们谈谈命令行方法。</p><h4 id="方法-2-更改登录配置-针对高级用户" tabindex="-1">方法 2：更改登录配置（针对高级用户） <a class="header-anchor" href="#方法-2-更改登录配置-针对高级用户" aria-label="Permalink to “方法 2：更改登录配置（针对高级用户）”">​</a></h4><p>如果你查看文件 <code>/etc/systemd/logind.conf</code> 的内容，你将看到三种不同类型的笔记本电脑合盖默认设置：</p><ul><li><code>HandleLidSwitch=suspend</code>：当笔记本电脑使用电池供电时，合盖挂起</li><li><code>HandleLidSwitchExternalPower=suspend</code>：当笔记本电脑插入电源插座时，合盖挂起</li><li><code>HandleLidSwitchDocked=ignore</code>：当笔记本电脑连接到扩展坞时，合盖忽略</li></ul><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/laptop-lid-settings-ubuntu.png" alt="Default laptop lid closing settings"></p><p>如你所见，如果合上盖子，笔记本电脑将挂起，无论它是否连接到电源。而连接扩展坞忽略合盖。</p><p>如果需要，你可以根据自己的喜好将这些参数的值更改为其中之一：</p><ul><li><code>suspend</code>：合盖时挂起</li><li><code>lock</code>：合盖时锁定</li><li><code>ignore</code>：什么都不做</li><li><code>poweroff</code>：关机</li><li><code>hibernate</code>：合盖时休眠</li></ul><p>如果你不希望你的系统在笔记本电脑盖合上时执行任何特殊操作，我建议你使用 <code>ignore</code>。</p><p>你可以编辑 <code>/etc/systemd/logind.conf</code> 文件，或者在 <code>/etc/systemd/logind.conf.d</code> 目录中创建一个新文件，并取消注释上述设置并更改其值。如果此目录不存在，请创建此目录。</p><p>我不会给你确切的命令。如果你熟悉命令行，你应该可以做到。如果你对命令行感到不习惯，请使用前面的 GUI 方法。</p><p>我希望这可以帮助你。如果你有任何问题，请告诉我。</p><hr>',17)),i("p",null,[t[4]||(t[4]=e("via: ",-1)),o(s,{href:"https://itsfoss.com/laptop-lid-suspend-ubuntu/"},{default:n(()=>[...t[3]||(t[3]=[e("https://itsfoss.com/laptop-lid-suspend-ubuntu/",-1)])]),_:1})]),i("p",null,[t[9]||(t[9]=e("作者：",-1)),o(s,{href:"https://itsfoss.com/"},{default:n(()=>[...t[5]||(t[5]=[e("Abhishek Prakash",-1)])]),_:1}),t[10]||(t[10]=e(" 选题：",-1)),o(s,{href:"https://github.com/lkxed"},{default:n(()=>[...t[6]||(t[6]=[e("lkxed",-1)])]),_:1}),t[11]||(t[11]=e(" 译者：",-1)),o(s,{href:"https://github.com/geekpi"},{default:n(()=>[...t[7]||(t[7]=[e("geekpi",-1)])]),_:1}),t[12]||(t[12]=e(" 校对：",-1)),o(s,{href:"https://github.com/wxy"},{default:n(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[15]||(t[15]=e("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原创编译，",-1)),o(s,{href:"https://linux.cn/"},{default:n(()=>[...t[14]||(t[14]=[e("Linux中国",-1)])]),_:1}),t[17]||(t[17]=e(" 荣誉推出",-1))])])}const x=l(r,[["render",b]]);export{C as __pageData,x as default};
